// Настройка: Run Once for All Items
const input = $input.item.json;

// Вариант 1: Пришел клик по кнопке (проброшенный из главного воркфлоу)
if (input.callback_query) {
    const cb = input.callback_query;
    const parts = cb.data.split('_'); // ['wiz', 'skip', '29']
    return [{
        json: {
            source: 'button_click',
            callback_query_id: cb.id,
            chat_id: cb.message.chat.id,
            message_id: cb.message.message_id,
            action: parts[1], // <-- ОБЯЗАТЕЛЬНО [1]
            task_id: Number(parts[2]) // <-- ОБЯЗАТЕЛЬНО [2]
        }
    }];
}


// Вариант 2: Пришел сигнал продолжить опрос после переноса задачи в ИИ
if (input.action === 'resume_wizard') {
    return [{
        json: {
            source: 'resume_after_move',
            chat_id: input.chat_id
        }
    }];
}

// Вариант 3: Плановый запуск по Cron в 21:00 (убираем старые галочки is_reviewed_today перед стартом)
return [{
    json: {
        source: 'cron_start'
    }
}];

const items = $input.all();
if (!items.length || !items[0].json.chat_id) return [];

const results = [];

for (const item of items) {
    const d = item.json;

    const isEdit = d.source === 'button_click' && d.message_id;
    const tgMethod = isEdit ? 'editMessageText' : 'sendMessage';

    let text = '';
    let replyMarkup = { inline_keyboard: [] };

    if (d.btn_action === 'move') {
        text = `➡️ *Перенос задачи:* «${d.acted_title}»\n\n✍️ Напиши текстом или надиктуй голосом, на какую дату и время её перенести? *(Например: «на четверг в 16:00» или «на завтра»)*`;
    } else if (d.next_id) {
        const mark = d.next_important ? '🔥 ' : '';
        const timeStr = d.next_time ? `\n🕒 Запланировано на: *${String(d.next_time).slice(0, 5)}*` : '';

        text = `🌙 *Вечерний чек-ин* (осталось задач: ${d.total_left})\n\n` +
               `📌 ${mark}*${d.next_title}*${timeStr}\n\n` +
               `Успел выполнить эту задачу сегодня?`;

        replyMarkup = {
            inline_keyboard: [
                [
                    { text: '✅ Да', callback_data: `wiz_done_${d.next_id}` },
                    { text: '❌ Нет', callback_data: `wiz_skip_${d.next_id}` },
                    { text: '➡️ Перенос', callback_data: `wiz_move_${d.next_id}` }
                ]
            ]
        };
    } else {
        text = `🎉 *Отличная работа!* Все задачи на сегодня разобраны. Хорошего вечера!`;
    }

    const payload = {
        chat_id: Number(d.chat_id),
        text: text,
        parse_mode: 'Markdown',
        reply_markup: replyMarkup
    };

    if (isEdit) {
        payload.message_id = Number(d.message_id);
    }

    results.push({
        json: {
            tg_method: tgMethod,
            callback_query_id: d.callback_query_id || null,
            payload: payload
        }
    });
}

return results;
